  const formatNumber=value=>new Intl.NumberFormat().format(Number(value||0));
  function renderAnalyticsRows(containerId,rows,isPage=false){const box=$(containerId);box.replaceChildren();if(!Array.isArray(rows)||!rows.length){box.append(el("div","hint","No recorded views yet."));return;}for(const row of rows){const item=el("div","analytics-row"+(isPage?" analytics-page-row":""));if(isPage)item.append(el("span","",row.path||"/"),el("span","views",`${formatNumber(row.views)} views`));else{const label=new Date(`${row.day}T00:00:00Z`).toLocaleDateString();item.append(el("span","",label),el("span","views",`${formatNumber(row.views)} views`),el("span","unique",`${formatNumber(row.unique)} unique`));}box.append(item);}}
  async function loadAnalytics(){scopedStatus("analytics-status","Loading analytics…");const {data,error}=await db.rpc("guide_analytics_summary");if(error){console.error(error);scopedStatus("analytics-status",error.message,"error");return;}const summary=data||{};$("analytics-total-views").textContent=formatNumber(summary.total_views);$("analytics-unique").textContent=formatNumber(summary.unique_visitors);$("analytics-today").textContent=formatNumber(summary.today_views);$("analytics-today-unique").textContent=formatNumber(summary.today_unique);renderAnalyticsRows("analytics-history",summary.daily);renderAnalyticsRows("analytics-pages",summary.top_pages,true);scopedStatus("analytics-status","Analytics updated. Counts begin from the tracker activation date.","success");}

  async function loadEntries(){setStatus("Loading database entries…");const {data,error}=await db.from("guide_database_entries").select("*").order("sort_order").order("name");if(error){console.error(error);setStatus(error.message,"error");return;}entries=Array.isArray(data)?data:[];setStatus(`Loaded ${entries.length} KaiokenMS database entries.`,"success");renderEntries();}
