      const card=el("article","item-card"+(row.enabled?"":" disabled")),icon=el("div","item-icon");if(row.image_url){const img=document.createElement("img");img.src=row.image_url;img.alt="";img.loading="lazy";img.onerror=()=>{icon.replaceChildren(el("span","placeholder","📦"));};icon.append(img);}else icon.append(el("span","placeholder",row.entity_type==="npc"?"🧑":row.entity_type==="feature"?"⚡":"📦"));
