      const actions=el("div","item-actions"),edit=el("button","","Edit"),image=el("button","","Image"),toggle=el("button","",row.enabled?"Disable":"Enable"),del=el("button","danger","Delete");edit.onclick=()=>openEdit(row);image.onclick=()=>{openEdit(row);setTimeout(()=>$('entry-image-preview')?.scrollIntoView({behavior:'smooth',block:'center'}),80);};toggle.onclick=()=>toggleEnabled(row);del.onclick=()=>deleteEntry(row);actions.append(edit,image,toggle,del);card.append(icon,main,actions);g.append(card);
