  function revokePreview(){if(previewObjectUrl){URL.revokeObjectURL(previewObjectUrl);previewObjectUrl=null;}}
  function showImagePreview(url=""){revokePreview();const box=$("entry-image-preview");box.replaceChildren();if(!url){box.append(el("span","","📦"));return;}const img=document.createElement("img");img.src=url;img.alt="Entry preview";img.onerror=()=>box.replaceChildren(el("span","","📦"));box.append(img);}
  function showLocalPreview(file){revokePreview();if(!file)return showImagePreview(clean($("entry-image-url").value,1200));previewObjectUrl=URL.createObjectURL(file);const box=$("entry-image-preview");box.replaceChildren();const img=document.createElement("img");img.src=previewObjectUrl;img.alt="New preview";box.append(img);}
  function managedImagePath(url){const v=clean(url,1400),marker="/storage/v1/object/public/guide-database-images/",i=v.indexOf(marker);if(i<0)return null;try{return decodeURIComponent(v.slice(i+marker.length));}catch{return v.slice(i+marker.length);}}
  async function cleanupManagedImage(url){const path=managedImagePath(url);if(!path)return;const {count,error:countError}=await db.from("guide_database_entries").select("id",{count:"exact",head:true}).eq("image_url",url);if(countError||Number(count||0)>0)return;const {error}=await db.storage.from("guide-database-images").remove([path]);if(error)console.warn("Storage cleanup failed",error);}
