  function payloadFromForm(){let metadata={};const raw=$("entry-metadata").value.trim();if(raw){try{metadata=JSON.parse(raw);}catch{throw new Error("Metadata JSON is not valid.");}}const name=clean($("entry-name").value,160),slug=slugify($("entry-slug").value||name),type=$("entry-type").value;if(!name||!slug)throw new Error("Name and slug are required.");if(!validTypes.has(type))throw new Error("Invalid entry type.");return{entity_type:type,slug,name,game_id:clean($("entry-game-id").value)?Number($("entry-game-id").value):null,category:clean($("entry-category").value,100)||null,subcategory:clean($("entry-subcategory").value,100)||null,aliases:clean($("entry-aliases").value,800).split(",").map(x=>clean(x,120)).filter(Boolean),description:clean($("entry-description").value,2000)||null,image_url:clean($("entry-image-url").value,1200)||null,verified:$("entry-verified").checked,enabled:$("entry-enabled").checked,sort_order:Number($("entry-sort").value||0),metadata};}
  async function saveEntry(ev){ev.preventDefault();scopedStatus("form-status","Saving…");try{const payload=payloadFromForm(),file=$("entry-image-file").files?.[0];if(file)payload.image_url=await uploadImage(file);else if(removeImageRequested)payload.image_url=null;const id=$("entry-id").value,query=id?db.from("guide_database_entries").update(payload).eq("id",id):db.from("guide_database_entries").insert(payload),{error}=await query;if(error)throw error;const old=originalImageUrl,newUrl=payload.image_url;entryDialog.close();await loadEntries();if(old&&old!==newUrl)await cleanupManagedImage(old);setStatus(`${payload.name} saved.`,"success");}catch(e){console.error(e);scopedStatus("form-status",e.message||"Save failed.","error");}}
