  function parseCSV(text){const rows=[];let row=[],field="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(quoted){if(c==='"'&&n==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else{if(c==='"')quoted=true;else if(c===','){row.push(field);field="";}else if(c==='\n'){row.push(field.replace(/\r$/,"") );rows.push(row);row=[];field="";}else field+=c;}}if(field.length||row.length){row.push(field.replace(/\r$/,"") );rows.push(row);}if(!rows.length)return[];const headers=rows.shift().map(h=>h.trim());return rows.filter(r=>r.some(v=>v.trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""])));}
  function rowToPayload(r){const name=clean(r.name,160),slug=slugify(r.slug||name),type=validTypes.has(r.entity_type)?r.entity_type:"other";if(!name||!slug)throw new Error("Every CSV row needs name/slug.");let metadata={};if(clean(r.metadata)){try{metadata=JSON.parse(r.metadata);}catch{throw new Error(`Invalid metadata JSON for ${name}`);}}return{slug,name,entity_type:type,game_id:clean(r.game_id)?Number(r.game_id):null,category:clean(r.category,100)||null,subcategory:clean(r.subcategory,100)||null,aliases:clean(r.aliases,1200).split("|").map(x=>clean(x,120)).filter(Boolean),description:clean(r.description,2000)||null,image_url:clean(r.image_url,1200)||null,verified:boolish(r.verified),enabled:r.enabled===""?true:boolish(r.enabled),sort_order:Number(r.sort_order||0),metadata};}
  async function importCSV(ev){ev.preventDefault();const file=$("csv-file").files?.[0];if(!file)return;scopedStatus("import-status","Reading CSV…");try{const raw=parseCSV(await file.text()).map(rowToPayload);if(!raw.length)throw new Error("CSV has no data rows.");for(let i=0;i<raw.length;i+=100){const {error}=await db.from("guide_database_entries").upsert(raw.slice(i,i+100),{onConflict:"slug"});if(error)throw error;}importDialog.close();await loadEntries();setStatus(`Imported ${raw.length} database rows.`,"success");}catch(e){console.error(e);scopedStatus("import-status",e.message||"Import failed.","error");}}
  function csvEscape(v){const s=String(v??"");return /[",\n\r]/.test(s)?`"${s.replaceAll('"','""')}"`:s;}
  function exportCSV(){const headers=["slug","name","entity_type","game_id","category","subcategory","aliases","description","image_url","verified","enabled","sort_order","metadata"],lines=[headers.join(",")];for(const x of entries){const row={...x,aliases:(x.aliases||[]).join("|"),metadata:JSON.stringify(x.metadata||{})};lines.push(headers.map(h=>csvEscape(row[h])).join(","));}const blob=new Blob(["\ufeff"+lines.join("\r\n")],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`kaioken-database-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}

  async function loadStaff(){if(role!=="editor")return;scopedStatus("team-status","Loading staff…");const {data,error}=await db.rpc("market_list_staff");if(error){scopedStatus("team-status",error.message,"error");return;}staff=Array.isArray(data)?data:[];scopedStatus("team-status",`Loaded ${staff.length} staff accounts.`,"success");renderStaff();}
