  async function setStaff(ev){ev.preventDefault();const uid=clean($("staff-user-id").value,80),r=$("staff-role").value;if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(uid)){scopedStatus("team-status","Invalid UUID format.","error");return;}const {error}=await db.rpc("market_set_staff_role",{p_user_id:uid,p_role:r});if(error){scopedStatus("team-status",error.message,"error");return;}$("staff-form").reset();await loadStaff();}
