  $("discord-login").onclick=async()=>{if(!db)return;const redirectTo=new URL("owner-console-7f4c9d2a.html",window.location.href).href;const {error}=await db.auth.signInWithOAuth({provider:"discord",options:{redirectTo}});if(error)setAccess("bad","Discord login failed",error.message);};
  $("sign-out").onclick=async()=>{await db.auth.signOut();await refreshAuth();};
  $("add-entry").onclick=openAdd;$("entry-name").addEventListener("input",()=>{if(!$("entry-id").value)$("entry-slug").value=slugify($("entry-name").value);});entryForm.addEventListener("submit",saveEntry);$("cancel-entry").onclick=()=>entryDialog.close();$("entry-image-file").addEventListener("change",e=>{removeImageRequested=false;showLocalPreview(e.target.files?.[0]);});$("entry-image-url").addEventListener("input",e=>{if(!$("entry-image-file").files?.length){removeImageRequested=false;showImagePreview(clean(e.target.value,1200));}});$("entry-remove-image").onclick=()=>{removeImageRequested=true;$("entry-image-url").value="";$("entry-image-file").value="";showImagePreview();scopedStatus("form-status","Image will be removed when you save.");};
  $("search").addEventListener("input",renderEntries);$("type-filter").addEventListener("change",renderEntries);$("enabled-filter").addEventListener("change",renderEntries);$("import-open").onclick=()=>{importForm.reset();$("import-status").textContent="";$("import-summary").textContent="Choose a CSV file. Rows are upserted by slug.";importDialog.showModal();};$("cancel-import").onclick=()=>importDialog.close();importForm.addEventListener("submit",importCSV);$("export-csv").onclick=exportCSV;$("csv-file").addEventListener("change",async()=>{const f=$("csv-file").files?.[0];if(!f)return;try{$("import-summary").textContent=`${f.name} • ${parseCSV(await f.text()).length} data rows detected`;}catch{$("import-summary").textContent="Could not preview CSV.";}});$("refresh-analytics").onclick=loadAnalytics;$("refresh-team").onclick=loadStaff;$("staff-form").addEventListener("submit",setStaff);

  async function init(){if(!configured||!window.supabase){setAccess("bad","Configuration missing","supabase-config.js must contain the Supabase Project URL and public publishable key.");return;}db=window.supabase.createClient(CONFIG.supabaseUrl,CONFIG.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});connectLiveViewers();db.auth.onAuthStateChange(()=>setTimeout(refreshAuth,0));await refreshAuth();}
